import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';

interface ChildNode {
  label: string;
  checked: boolean;
}

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly children = signal<ChildNode[]>([
    { label: 'Child 1', checked: false },
    { label: 'Child 2', checked: false },
    { label: 'Child 3', checked: false }
  ]);

  readonly checkedCount = computed(() => this.children().filter((child) => child.checked).length);
  readonly allChecked = computed(() => this.checkedCount() === this.children().length);
  readonly someChecked = computed(() => this.checkedCount() > 0 && !this.allChecked());

  toggleParent(event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;
    this.children.update((children) => children.map((child) => ({ ...child, checked })));
  }

  toggleChild(index: number): void {
    this.children.update((children) =>
      children.map((child, i) => (i === index ? { ...child, checked: !child.checked } : child))
    );
  }
}
